"""Normalize release records at the input boundary."""


class JournalError(ValueError):
    pass


def _id_list(entries, error):
    """Validate a JSON array of nonempty change IDs.

    `depends_on`, `applied` and `retain` share this shape. A bare string, an
    object, a number or a null is a malformed field, not an empty one; and the
    empty string does not name a change, so it is malformed too.
    """
    if not isinstance(entries, list):
        raise JournalError(error)
    for entry in entries:
        if not isinstance(entry, str) or not entry:
            raise JournalError(error)
    return entries


def _read_dependencies(row):
    return _id_list(row.get("depends_on", []), "invalid-change")


def read_changes(records):
    """Validate records, collapse identical duplicates and reject conflicting IDs."""
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    unique = {}
    for row in records:
        if (not isinstance(row, dict) or not isinstance(row.get("id"), str) or not row["id"]
                or not isinstance(row.get("component"), str) or not row["component"]
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        change = {
            "id": row["id"],
            "component": row["component"],
            "units": row["units"],
            "depends_on": frozenset(_read_dependencies(row)),
        }
        previous = unique.get(change["id"])
        if previous is None:
            unique[change["id"]] = change
        elif previous != change:
            raise JournalError("conflicting-change")
    return [unique[key] for key in sorted(unique)]


def read_applied(journal):
    """Validate the persisted release journal and return its unique change IDs."""
    return set(_id_list(journal, "invalid-change"))


BATCH_ITEM_FIELDS = frozenset(("environment", "budget", "changes", "applied", "retain"))
OPERATION_ID_FIELD = "operation_id"
OPERATION_ID_MAX_LENGTH = 64


def read_operation_id(item):
    """G4: validate one batch item's `operation_id` and return it verbatim.

    The ID is a nonempty string of at most 64 characters -- counted, as JSON
    itself counts, in UTF-8 bytes -- compared exactly as supplied, with no
    trimming or normalization, because it is the caller's idempotency key. It is
    checked next to the item's structure, before any business validation of the
    item's content.
    """
    operation_id = item.get(OPERATION_ID_FIELD)
    if not isinstance(operation_id, str) or not operation_id:
        raise JournalError("invalid-batch-item")
    try:
        too_long = len(operation_id.encode("utf-8", "surrogatepass")) > OPERATION_ID_MAX_LENGTH
    except UnicodeEncodeError:
        # A lone surrogate cannot be sent as JSON text, so it is not an ID.
        raise JournalError("invalid-batch-item") from None
    if too_long:
        raise JournalError("invalid-batch-item")
    return operation_id


def _typed(value):
    """Describe a JSON value as (type tag, payload) so equal types must match.

    Python treats `1`, `1.0`, `True` and `1+0j` as equal, but JSON numbers and
    booleans are separate types and ints and floats are separate spellings.
    Tagging the type keeps all four apart while still comparing payloads by
    value, recursively, with object keys order-free and array order preserved.
    The result is hashable so a whole item's data can serve as one key.
    """
    if isinstance(value, dict):
        return ("object", frozenset((key, _typed(inner)) for key, inner in value.items()))
    if isinstance(value, list):
        return ("array", tuple(_typed(inner) for inner in value))
    if isinstance(value, bool):
        return ("boolean", value)
    if value is None:
        return ("null", None)
    return (type(value).__name__, value)


def item_data(item):
    """G4: a comparison key for an item's request data, minus its operation ID.

    Two items are retries of each other when their IDs are equal and so are
    their data under `_typed`: object field order is irrelevant, array order is
    not, and JSON numbers and booleans never compare equal.
    """
    return frozenset(
        (key, _typed(value)) for key, value in item.items() if key != OPERATION_ID_FIELD
    )


def read_batch_item(item):
    """Validate one `rollback-many` item and return it as a normalized request.

    An item is a single rollback request with `action` implied, so its fields are
    exactly environment, budget, changes, applied, retain and the G4 operation_id;
    `action` and any other key mean the item is shaped for something else and is
    rejected whole. The operation ID is read first -- it is part of the item's
    shape, not its content -- and the values are otherwise checked by the
    ordinary single-request readers, so a batch item fails with the same error
    codes as an equivalent standalone rollback.
    """
    if not isinstance(item, dict):
        raise JournalError("invalid-batch-item")
    operation_id = read_operation_id(item)
    if not set(item) <= BATCH_ITEM_FIELDS | {OPERATION_ID_FIELD} or "environment" not in item:
        raise JournalError("invalid-batch-item")
    normalized = dict(item)
    normalized["action"] = "rollback"
    return normalized, operation_id


def read_retain(request, applied):
    """Read the G2 rollback `retain` list: applied IDs that must remain installed.

    `retain` defaults to empty. Malformed lists are rejected here; an ID that is
    a valid string but was never applied is rejected here too, because that needs
    the persisted journal and no other module is allowed to own it. Repeated IDs
    are harmless; the value is consumed as a set.
    """
    retained = set(_id_list(request.get("retain", []), "invalid-retain"))
    if not retained <= applied:
        raise JournalError("invalid-retain")
    return retained

