from planner import plan, plan_batch

# G3: the only dispatch decision made at the transport layer. Detection is by
# the *value* of the top-level `action`, so every G1/G2 request that does not
# use this action keeps its old code path and old error shape untouched --
# including requests that happen to carry unrelated extra fields.
BATCH_ACTION = "rollback-many"


def main():
    try:
        request = json.load(sys.stdin)
    except (ValueError, TypeError):
        result = {"status": "error", "error": "invalid-json", "actions": [], "units": 0}
    else:
        # A non-object request cannot be a batch; let planner.plan answer with
        # the historical `invalid-request` instead of `invalid-batch`.
        if isinstance(request, dict) and request.get("action") == BATCH_ACTION:
            result = plan_batch(request)
        else:
            result = plan(request)
    print(json.dumps(result, separators=(",", ":")))


if __name__ == "__main__":
    main()

