            raise JournalError("unknown-dependency")
        order = topological_order(by_id)
        if policy.action == "rollback":
            retained = read_retain(request, applied)
            actions = rollback_actions(by_id, order, applied, retained)
        else:
            actions = [key for key in order if key not in applied]
            if sum(by_id[key]["units"] for key in actions) > policy.limit:
                return failure("budget-exceeded")
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    units = sum(by_id[key]["units"] for key in actions)
    return {"status": "ok", "actions": actions, "units": units}


def rollback_item(request):
    """Evaluate one G3 batch item as a single rollback; return (actions, units).

    The item is not reimplemented here. It is fed through the same `plan` entry
    the single-request path uses, after pinning `action` to rollback, so batch
    items inherit the G2 staging-only freeze, the graph/replay/retain rules and
    the "budget validated but not capped for rollback" rule by construction.
    Any divergence between single and batch rollback would be a bug here.

    `plan` reports a business problem as a failed result object rather than an
    exception; the caller turns any non-ok status back into a batch failure
    carrying that same error code.
    """
    item = dict(request)
    # G3 omits `action`: the batch entry decides it. Assigning (not setdefault)
    # keeps this true even if a caller smuggled an `action` key in (journal's
    # structural gate rejects that, this is only defense in depth).
    item["action"] = "rollback"
    result = plan(item)
    if result["status"] != "ok":
        raise JournalError(result["error"])
    return result["actions"], result["units"]


def plan_batch(request):
    """G3 `rollback-many`: evaluate independent rollback items in order.

    Two passes, deliberately:
      1. envelope + structural checks for *every* item, in order;
      2. business evaluation item by item, in order.
    The first pass means a malformed item at index 5 is reported even if item 0
    would fail on business grounds, and the second means the first real business
    failure (lowest index) ends the batch. Nothing is emitted until every item
    has succeeded, so a failure never leaves partial results behind.
    """
    try:
        requests = read_batch(request)
    except JournalError as exc:
        # Top-level defects carry a null index: there is no offending item.
        return batch_failure(str(exc), None)
    try:
        for index, item in enumerate(requests):
            read_batch_item(item, index)
    except JournalError as exc:
        # The structural pass reports its own code (`invalid-batch-item`) and the
        # index of the offending element, never a business code.
        return batch_failure(str(exc), index)
    results = []
    total = 0
    for index, item in enumerate(requests):
        try:
            actions, units = rollback_item(item)
        except JournalError as exc:
            # First business failure wins and ends the batch; results stay empty
            # even though earlier items succeeded (no partial results).
            return batch_failure(str(exc), index)
        results.append({"actions": actions, "units": units})
        total += units
    return {"status": "ok", "results": results, "units": total}

