"""Compose policy and journal data into a plan."""
import heapq

from journal import (JournalError, read_applied, read_batch, read_batch_item,
                     read_changes, read_retain)
from policy import PolicyError, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def batch_failure(code, index):
    """G3 failure shape: indexed, empty results, zero units.

    `requestIndex` is always present, even for top-level failures where there is
    no offending item; those use None rather than 0 so a caller can tell "the
    batch envelope is wrong" from "item 0 is wrong".
    """
    return {"status": "error", "error": code, "requestIndex": index, "results": [], "units": 0}


def build_graph(changes):
    """Index changes by ID and verify that every dependency target exists."""
    by_id = {row["id"]: row for row in changes}
    for row in changes:
        for target in row["depends_on"]:
            if target not in by_id:
                raise JournalError("unknown-dependency")
    return by_id


def topological_order(by_id):
    """Kahn's algorithm with lexicographic tie-breaking among eligible changes.

    The order covers every change, applied or not, so a cycle or a dangling
    reference is detected even when the emitted action list would be empty.
    """
    pending = {key: len(by_id[key]["depends_on"]) for key in by_id}
    dependents = {key: [] for key in by_id}
    for key in by_id:
        for target in by_id[key]["depends_on"]:
            dependents[target].append(key)
    eligible = [key for key, count in pending.items() if not count]
    heapq.heapify(eligible)
    order = []
    while eligible:
        key = heapq.heappop(eligible)
        order.append(key)
        for dependent in dependents[key]:
            pending[dependent] -= 1
            if not pending[dependent]:
                heapq.heappush(eligible, dependent)
    if len(order) != len(by_id):
        raise JournalError("dependency-cycle")
    return order


def retained_closure(by_id, applied, retained):
    """`retained` plus the transitive dependencies it needs, limited to applied ones.

    A retained change must stay installed, so whatever it depends on must stay
    too. The walk must continue *through* unapplied nodes: an unapplied
    dependency is not installed and is therefore never kept, but its own
    dependencies may be installed and still required by the retained change.
    So c(retained, applied) -> b(unapplied) -> a(applied) keeps a, because a is
    present and c still needs it; only pruning applied nodes (as an earlier
    version was thought to do) silently leaves that tree half-removed.

    `applied` bounds the result, not the traversal: the walk is over the full
    dependency graph, which is also why a 2,000-node chain costs one linear pass
    and no recursion.
    """
    keep = set(retained)
    stack = list(retained)
    visited = set(retained)
    while stack:
        for target in by_id[stack.pop()]["depends_on"]:
            if target not in visited:
                visited.add(target)
                stack.append(target)
                if target in applied:
                    keep.add(target)
    return keep


def rollback_actions(by_id, order, applied, retained):
    """Applied IDs in reverse execution order, minus retained changes and their needs."""
    keep = retained_closure(by_id, applied, retained)
    return [key for key in reversed(order) if key in applied and key not in keep]


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        # The environment/action/budget check comes first so a frozen production
        # request is reported before any graph or change validation runs.
        policy = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied", []))
        by_id = build_graph(changes)
        if not applied <= by_id.keys():
            raise JournalError("unknown-dependency")
        order = topological_order(by_id)
        if policy.action == "rollback":
            retained = read_retain(request, applied)
            actions = rollback_actions(by_id, order, applied, retained)
        else:
            actions = [key for key in order if key not in applied]
            if sum(by_id[key]["units"] for key in actions) > policy.limit:
                return failure("budget-exceeded")
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    units = sum(by_id[key]["units"] for key in actions)
    return {"status": "ok", "actions": actions, "units": units}


def rollback_item(request):
    """Evaluate one batch item as a single rollback; return (actions, units).

    The item is not reimplemented here. It is fed through the same `plan` entry
    the single-request path uses, after pinning `action` to rollback, so batch
    items inherit the G2 staging-only freeze, the graph/replay/retain rules and
    the "budget validated but not capped for rollback" rule by construction.
    Any divergence between single and batch rollback would be a bug here.

    `plan` reports a business problem as a failed result object rather than an
    exception; the caller turns any non-ok status back into a batch failure
    carrying that same error code.

    G4 calls this only for the *first* occurrence of an operation_id, so the
    batch `limit` is never applied here: the single-rollback path has no notion
    of a batch quota, and threading one in would leak batch state into G2.
    """
    item = dict(request)
    # The batch entry decides the action. Assigning (not setdefault) makes that
    # true even if a caller supplied an `action` key; the item is allowed to
    # carry one for forward-compatibility (see journal.BATCH_ITEM_FIELDS) and it
    # is simply overridden.
    item["action"] = "rollback"
    result = plan(item)
    if result["status"] != "ok":
        raise JournalError(result["error"])
    return result["actions"], result["units"]


def plan_batch(request):
    """`rollback-many`: evaluate independent rollback items in order (G3 + G4).

    Order of precedence is exactly the G4 revision's, and it is the whole reason
    this function is structured the way it is:

      1. envelope (action/limit/requests)              -> invalid-batch, index None
      2. structure of *every* item, in order            -> invalid-batch-item, index i
      3. per item, in order: replay / conflict decision  -> conflicting-operation, index i
         then, only for a new operation_id, the G2 rules -> that item's own code, index i
      4. after the whole batch is clean: compare the
         deduplicated units against `limit`             -> batch-limit-exceeded, index None
      5. commit

    Pass 2 is separate from passes 3/4 so a malformed item at index 5 outranks a
    business failure at index 0. Pass 4 runs last for the mirror-image reason: a
    quota verdict is only meaningful once nothing else is wrong, so the batch
    reports the real defect instead of a budget symptom of it.

    Nothing is emitted until the very end, so no failure can leave partial
    results behind.
    """
    try:
        requests, limit = read_batch(request)
    except JournalError as exc:
        # Top-level defects carry a null index: there is no offending item.
        return batch_failure(str(exc), None)
    try:
        for index, item in enumerate(requests):
            read_batch_item(item, index)
    except JournalError as exc:
        # The structural pass reports its own code (`invalid-batch-item`) and the
        # index of the offending element, never a business code.
        return batch_failure(str(exc), index)

    # operation_id -> (canonical request data, emitted result). Only the *first*
    # occurrence of an id is ever evaluated; see the replay comment below.
    seen = {}
    results = []
    # Units actually charged. A replay appends a result but is not added here,
    # which makes this sum equal "units of all rollback actions after
    # deduplication" -- the quantity G4 compares against `limit`. Keeping one
    # accumulator instead of computing a separate quota total is deliberate:
    # two totals would be two places to drift apart.
    charged = 0
    for index, item in enumerate(requests):
        operation_id = item["operation_id"]
        fingerprint = _fingerprint(item)
        previous = seen.get(operation_id)
        if previous is not None:
            stored_fingerprint, stored_result = previous
            if stored_fingerprint != fingerprint:
                # Same id, different data. The index points at this *later* item
                # because the earlier one was accepted first -- the retry that
                # changed its payload is the defect. This is decided before the
                # item's own G2 checks: a conflicting payload is a conflict even
                # if it would also have been invalid on its own terms.
                return batch_failure("conflicting-operation", index)
            # Identical retry: echo the first result, charge nothing. The unit
            # count comes from the stored result rather than a recomputation so
            # a replay can never disagree with the call it replays.
            units = stored_result["units"]
            results.append({"actions": list(stored_result["actions"]),
                            "units": units, "operationId": operation_id})
            continue
        try:
            # First sighting of this id: the only path that runs business rules.
            actions, units = rollback_item(item)
        except JournalError as exc:
            # The first actual business failure wins and ends the batch, before
            # the batch quota is ever consulted (G4: failure outranks limit).
            return batch_failure(str(exc), index)
        stored_result = {"actions": actions, "units": units}
        seen[operation_id] = (fingerprint, stored_result)
        results.append({"actions": list(actions), "units": units,
                        "operationId": operation_id})
        charged += units

    if charged > limit:
        # Whole-batch quota, checked only here and only against deduplicated
        # units. An equal total is allowed. The null index says "the batch as a
        # whole is over budget", not "this item is at fault".
        return batch_failure("batch-limit-exceeded", None)
    return {"status": "ok", "results": results, "units": charged}


def _canonical(value):
    """Type-faithful, key-order-insensitive structure for G4 request comparison.

    Three rules from the revision, each mapping to one branch below:

    * "对象字段顺序不影响等价": dicts become tuples sorted by key, so two requests
      that differ only in presentation compare equal.
    * "数组顺序保留": lists become tuples in their given order, so reordering
      `applied`, `retain` or `depends_on` makes two requests *unequal*.
    * "JSON 数字和布尔值不能混同": Python says `True == 1` and hashes them alike
      (`{"a": True} == {"a": 1}`), so a naive tuple would call those equal. The
      `type(value)` tag in every leaf prevents that collision, and also keeps
      `1` and `1.0` distinguishable as JSON *literals* even though JSON has one
      number type and Python's `==` agrees they are numerically equal.
    """
    if isinstance(value, dict):
        return ("object", tuple((key, _canonical(item))
                                for key, item in sorted(value.items())))
    if isinstance(value, list):
        return ("array", tuple(_canonical(item) for item in value))
    return ("value", type(value).__name__, value)


# `operation_id` is the identity, not part of the payload; `action` is forced to
# rollback for every batch item before evaluation (see rollback_item), so an
# item that spells it out and one that omits it are the same request.
_FINGERPRINT_EXCLUDED = frozenset({"operation_id", "action"})


def _fingerprint(item):
    """Canonical form of an item's request data, used for replay vs conflict."""
    return _canonical({key: value for key, value in item.items()
                       if key not in _FINGERPRINT_EXCLUDED})

