"""Compose policy and journal data into a plan.

Planner is the top of the project import chain: it reads policy decisions and
normalized journal values, builds the dependency graph, and assembles the one
response object. Nothing below it sees a graph, an order or a budget.
"""
import heapq

from journal import JournalError, read_applied, read_batch_item, read_changes, read_retain
from policy import PolicyError, batch_requests, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def build_graph(changes):
    """Index changes by ID and verify that every dependency target exists.

    An empty dependency set is inserted for every change with no explicit
    `depends_on`, so ordering does not depend on input record order.
    """
    by_id = {row["id"]: row for row in changes}
    for row in changes:
        for target in row["depends_on"]:
            if target not in by_id:
                raise JournalError("unknown-dependency")
    return by_id


def topological_order(by_id):
    """Kahn's algorithm with lexicographic tie-breaking among eligible changes.

    The order covers every change, applied or not, so a cycle or a dangling
    reference is detected even when the emitted action list would be empty.
    """
    pending = {key: len(by_id[key]["depends_on"]) for key in by_id}
    dependents = {key: [] for key in by_id}
    for key in by_id:
        for target in by_id[key]["depends_on"]:
            dependents[target].append(key)
    eligible = [key for key, count in pending.items() if not count]
    heapq.heapify(eligible)
    order = []
    while eligible:
        key = heapq.heappop(eligible)
        order.append(key)
        for dependent in dependents[key]:
            pending[dependent] -= 1
            if not pending[dependent]:
                heapq.heappush(eligible, dependent)
    if len(order) != len(by_id):
        raise JournalError("dependency-cycle")
    return order


def retained_closure(by_id, applied, retained):
    """`retained` plus the transitive dependencies it needs, limited to applied ones.

    A retained change must stay installed, so whatever it depends on must stay
    too. An unapplied dependency is not installed and so is never kept, but the
    walk continues through it: c -> b(unapplied) -> a still keeps a when c is
    retained, because a is installed and c still needs it.

    The walk is iterative and each ID enters the stack at most once, so a long
    dependency chain cannot exhaust the Python recursion limit.
    """
    keep = set(retained)
    stack = list(retained)
    while stack:
        for target in by_id[stack.pop()]["depends_on"]:
            if target in applied and target not in keep:
                keep.add(target)
                stack.append(target)
    return keep


def rollback_actions(by_id, order, applied, retained):
    """Applied IDs in reverse execution order, minus retained changes and their needs."""
    keep = retained_closure(by_id, applied, retained)
    return [key for key in reversed(order) if key in applied and key not in keep]


def plan(request):
    """Single-request entrypoint; `release.py` calls this once per process."""
    if not isinstance(request, dict):
        return failure("invalid-request")
    # A batch outer shape is answered here because the entrypoint hands every
    # parsed value to planner; a missing or mislabeled action in the request is
    # still handled by policy below.
    if request.get("action") == "rollback-many":
        return batch(request)
    try:
        # The environment/action/budget check comes first so a frozen production
        # request is reported before any graph or change validation runs.
        policy = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied", []))
        by_id = build_graph(changes)
        if not applied <= by_id.keys():
            raise JournalError("unknown-dependency")
        order = topological_order(by_id)
        if policy.action == "rollback":
            retained = read_retain(request, applied)
            actions = rollback_actions(by_id, order, applied, retained)
        else:
            actions = [key for key in order if key not in applied]
            # A plan without a budget cannot be capped, so it is a bad budget
            # rather than a default of 0 (which would silently emit nothing).
            if policy.action == "plan" and "budget" not in request:
                return failure("invalid-budget")
            if sum(by_id[key]["units"] for key in actions) > policy.limit:
                return failure("budget-exceeded")
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    units = sum(by_id[key]["units"] for key in actions)
    return {"status": "ok", "actions": actions, "units": units}


def batch_failure(code, index=None):
    """G3 failure: the batch error plus the failing item's 0-based index.

    A transport-level batch problem has no item to blame, so `requestIndex` is
    null there; an item failure always carries its real position. `results`
    stays empty because a failed batch has no partial results.
    """
    return {"status": "error", "error": code, "requestIndex": index,
            "results": [], "units": 0}


def batch(request):
    """Run each `rollback-many` item and assemble the ordered batch result."""
    try:
        requests = batch_requests(request)
    except PolicyError as exc:
        return batch_failure(str(exc))
    results = []
    total = 0

    # Items run one at a time in request order and each one is parsed from its
    # own dict. Nothing (graph, applied set, retain set, budget) is shared
    # between items, so one item cannot make another succeed or fail. The
    # first failure ends the batch before its result is appended, which is what
    # keeps the answer free of partial results; since nothing is executed (this
    # planner only emits actions), stopping early has no side effects to undo.
    for index, item in enumerate(requests):
        try:
            result = plan(read_batch_item(item))
        except JournalError as exc:
            return batch_failure(str(exc), index)
        except (PolicyError, ValueError, TypeError, KeyError, AttributeError):
            # An item that slips past the shape check but breaks a domain rule
            # deep in the graph would otherwise abort the whole process. It is
            # reported as a malformed item with its real index instead, still
            # ending the batch before any partial result is appended.
            return batch_failure("invalid-batch-item", index)
        if result["status"] != "ok":
            return batch_failure(result["error"], index)
        results.append({"actions": result["actions"], "units": result["units"]})
        total += result["units"]
    return {"status": "ok", "results": results, "units": total}

