"""JSON transport for the release planner.

Entrypoint only: decode stdin, hand the decoded value to planner (which routes
single requests and `rollback-many` batches), print exactly one JSON line and
exit normally. Every input -- bad JSON and domain errors included -- must yield
one JSON object and a normal exit; callers rely on that rather than on the exit
status.
"""
import json
import sys

from planner import plan

RECOVERY_ERROR = {"status": "error", "error": "invalid-request", "actions": [], "units": 0}


def main():
    try:
        request = json.load(sys.stdin)
    except ValueError:
        result = {"status": "error", "error": "invalid-json", "actions": [], "units": 0}
    else:
        # The contract is one JSON object per input no matter what, so the
        # planner call is guarded: an unexpected internal error still yields a
        # single JSON error object and a normal exit rather than a traceback.
        try:
            result = plan(request)
        except Exception:
            result = dict(RECOVERY_ERROR)
    print(json.dumps(result, separators=(",", ":")))


if __name__ == "__main__":
    main()

