"""JSON transport for the release planner."""
import json
import sys

from planner import plan

BATCH_ACTION = "rollback-many"

# G4: the batch wrapper accepts exactly these three top-level fields. `limit` is
# a batch-only quota; it never reaches the single-request pipeline.
BATCH_KEYS = frozenset({"action", "limit", "requests"})
BATCH_ITEM_KEYS = frozenset(
    {"environment", "budget", "changes", "applied", "retain", "operation_id"})

OPERATION_ID_MAX = 64


def batch_failure(code, index):
    return {"status": "error", "error": code, "requestIndex": index,
            "results": [], "units": 0}


def check_batch(request):
    """Structural check for a `rollback-many` wrapper; `(None, None)` means it may proceed.

    Transport owns this shape because it is the same kind of framing as
    `invalid-json`/`invalid-request`: the top-level fields, `limit`, the request
    list's size and each item's container/field/operation IDs are checked here.
    The contents of each item belong to the single-request pipeline, which
    re-validates every business rule.
    A batch-level problem has no request index (null); an item-level problem
    reports the index of the offending item.
    """
    if not isinstance(request, dict):
        return "invalid-batch", None
    if set(request) - BATCH_KEYS:
        return "invalid-batch", None
    # G4: `limit` is required, nonnegative and a real integer (booleans are not
    # integers here). A malformed limit is a wrapper problem, not an item one.
    limit = request.get("limit")
    if type(limit) is not int or limit < 0:
        return "invalid-batch", None
    requests = request.get("requests")
    if not isinstance(requests, list) or not 1 <= len(requests) <= 128:
        return "invalid-batch", None
    for index, item in enumerate(requests):
        if not isinstance(item, dict) or set(item) - BATCH_ITEM_KEYS:
            return "invalid-batch-item", index
        operation_id = item.get("operation_id")
        if (not isinstance(operation_id, str) or not operation_id
                or len(operation_id) > OPERATION_ID_MAX):
            return "invalid-batch-item", index
    return None, None


# Fields whose value is a set of names rather than an ordered list: G1/G2 treat
# `depends_on`, `applied` and `retain` as sets (and the single pipeline reads
# `depends_on` into a frozenset), so two items that differ only in the order of
# these names are the same request, exactly as they are for replay/dedup.
_SET_FIELDS = frozenset({"depends_on", "applied", "retain"})


def same_request(left, right):
    """True when two items carry equivalent request data.

    JSON equality with the G4 rules: object field order is irrelevant, array
    order is significant, and numbers and booleans never compare equal (Python
    alone would treat `1`, `1.0` and `True` as interchangeable, so the type is
    part of the comparison). The set-like journal fields above are the one
    exception, matching their G1 semantics. `operation_id` is not request data;
    it is already known to be identical when two items reach here.
    """
    if type(left) is not type(right):
        return False
    if isinstance(left, dict):
        if set(left) != set(right):
            return False
        for key in left:
            if key in _SET_FIELDS and isinstance(left[key], list):
                if not same_name_set(left[key], right[key]):
                    return False
            elif not same_request(left[key], right[key]):
                return False
        return True
    if isinstance(left, list):
        return (len(left) == len(right)
                and all(same_request(a, b) for a, b in zip(left, right)))
    return left == right


def same_name_set(left, right):
    """Compare two name lists as multisets of type-exact values."""
    if not isinstance(right, list) or len(left) != len(right):
        return False
    remaining = list(right)
    for value in left:
        for position, candidate in enumerate(remaining):
            if same_request(value, candidate):
                del remaining[position]
                break
        else:
            return False
    return True


def run_batch(request):
    """Execute every item in order and report the first failure for the batch.

    A batch never emits partial results: the first failing item's own error
    code ends the whole response. An item's `action` is forced to `rollback`,
    so a missing or mismatched action is not an item error.

    G4 processing order: per item, first the item's own structure and operation
    ID (checked in `check_batch` before any item runs), then duplicate/conflict
    resolution, and only for a new operation ID the G2 validation and
    computation. A repeated operation ID with identical request data is a retry:
    it reuses the first result and is not billed twice. Only once the whole
    batch has processed cleanly is the deduplicated total compared with the
    batch `limit`, so an actual item failure always outranks the quota.
    """
    results = []
    by_operation = {}
    units = 0
    for index, item in enumerate(request["requests"]):
        operation_id = item["operation_id"]
        data = {key: value for key, value in item.items() if key != "operation_id"}
        previous = by_operation.get(operation_id)
        if previous is not None:
            if not same_request(previous[1], data):
                return batch_failure("conflicting-operation", index)
            results.append(previous[0])
            continue
        single = dict(data)
        single["action"] = "rollback"
        outcome = plan(single)
        if outcome["status"] != "ok":
            return batch_failure(outcome["error"], index)
        result = {"actions": outcome["actions"], "units": outcome["units"],
                  "operationId": operation_id}
        by_operation[operation_id] = (result, data)
        results.append(result)
        units += outcome["units"]
    if units > request["limit"]:
        return batch_failure("batch-limit-exceeded", None)
    return {"status": "ok", "results": results, "units": units}


def main():
    try:
        request = json.load(sys.stdin)
    except (ValueError, TypeError):
        result = {"status": "error", "error": "invalid-json", "actions": [], "units": 0}
    else:
        if isinstance(request, dict) and request.get("action") == BATCH_ACTION:
            error, index = check_batch(request)
            result = batch_failure(error, index) if error else run_batch(request)
        else:
            result = plan(request)
    print(json.dumps(result, separators=(",", ":")))


if __name__ == "__main__":
    main()

