    shortest form that round-trips, so `1`, `1.0` and `1e0` all reduce to the same
    text while `1.5` and `2` stay apart. Booleans, strings and null keep their own
    tags and can never equal a number.

    A value that cannot be canonicalised (a composite key, a foreign object)
    returns the sentinel below, which never equals a string fingerprint and is
    not equal to itself, so such an item is always treated as a new operation
    instead of being silently merged as a retry.
    """
    try:
        return json.dumps(_tagged(value), separators=(",", ":"),
                          ensure_ascii=False)
    except (TypeError, ValueError):
        return _UNCANONICAL


def _number_text(value):
    """Normalised text of a JSON number, so equal numbers share one fingerprint."""

    if isinstance(value, int):
        return str(value)
    # Integers that arrived as `1.0`/`1e0` are the same number as `1`.
    if value.is_integer():
        return str(int(value))
    # `repr` is the shortest string that round-trips a float, so two floats are
    # written identically exactly when they hold the same value.
    return repr(value)


def _tagged(value):
    """Rebuild `value` with type tags, sorted object keys, arrays kept in order."""

    if value is None:
        return ["null"]
    if isinstance(value, bool):
        # Checked before int: bool is an int subclass but a distinct JSON kind.
        return ["bool", value]
    if isinstance(value, (int, float)):
        return ["number", _number_text(value)]
    if isinstance(value, str):
        return ["str", value]
    if isinstance(value, list):
        return ["list", [_tagged(item) for item in value]]
    if isinstance(value, dict):
        return ["dict", [[key, _tagged(value[key])] for key in sorted(value)]]
