class _Uncanonical(float):
    """A NaN-like sentinel that never compares equal, not even to itself."""

    def __eq__(self, other):
        return False

    __hash__ = None


_UNCANONICAL = _Uncanonical("nan")


# G4: `limit` is a top-level field of the batch envelope, so it is validated
# with the rest of the envelope before any element is looked at. The transport
# layer checks the permitted field set; this function owns the value rule
# (nonnegative integer, booleans rejected) and the planner re-reads it because
# the ceiling is compared only after every item has been processed.

def read_batch_limit(request):
    """Validate the G4 batch `limit`: a required nonnegative integer, no bools."""

    limit = request.get("limit")
    # type() rather than isinstance() so `true`/`false` never count as a limit,
    # exactly like the single-item budget rule in policy.limit_for.
    if type(limit) is not int or limit < 0:
        return None
    return limit


def rollback_many(request):
    """G4 batch rollback: deduplicate by operation ID, then run each new item.

    Order of work, which the error precedence depends on:
    1. the batch envelope: `limit` and the 1-128 item count -- `invalid-batch`
       with a null index, because no element was picked out yet;
    2. per item, in request order: element structure and `operation_id` --
       `invalid-batch-item` at that index with no domain validation yet, then
       operation identity -- `conflicting-operation` at the later item that
       reuses an ID with different data;
    3. only for a new operation, the single-item G2 rollback path. A retry is
       never evaluated, so it can neither fail nor be charged twice;
    4. only after every item passed 2 and 3, the deduplicated units are summed
       and compared with `limit` -- `batch-limit-exceeded` with a null index.

    The first real failure therefore always beats the batch ceiling, and every
    error shape stays atomic: no results and zero units. Items are otherwise
    independent -- each gets its own environment, change set, journal and
    retain set, and no graph, applied set or memo crosses between them -- so
    two different operation IDs with identical parameters each really run.
    """
    limit = read_batch_limit(request)
    if limit is None:
        return batch_failure("invalid-batch", None)
    items = request.get("requests")
    # Batch shape (item count) is checked before any element is evaluated, so an
    # empty or oversized list is `invalid-batch` rather than a per-item error.
    if (not isinstance(items, list) or not BATCH_MIN_ITEMS <= len(items) <= BATCH_MAX_ITEMS):
        return batch_failure("invalid-batch", None)
    results = []
    seen = {}
    for index, item in enumerate(items):
        # Element structure first: a non-object, a foreign field or a bad
        # operation ID is `invalid-batch-item` at this index. Only structurally
        # valid elements reach the domain checks, which then report their own
        # error code.
        if not isinstance(item, dict) or set(item) - BATCH_ITEM_FIELDS:
            return batch_failure("invalid-batch-item", index)
        operation_id = _read_operation_id(item)
        if operation_id is None:
            return batch_failure("invalid-batch-item", index)
        # Fingerprint the whole item, not just the rollback parameters: a retry
        # is a resend of the same request, so any difference at all (a changed
        # retain list included) is a different operation under the same ID.
        fingerprint = _canonical(item)
        previous = seen.get(operation_id)
        if previous is not None:
            # Same ID, same data: a client retry. Keep the first result, do not
            # evaluate again and do not charge its units a second time.
            if previous == fingerprint:
                continue
            return batch_failure("conflicting-operation", index)
        seen[operation_id] = fingerprint
        # Copy before adding `action`: the caller's element object must not be
        # mutated, since each item is meant to be independent of the batch frame.
        single = dict(item)
        del single["operation_id"]
        single["action"] = "rollback"
        try:
            outcome = evaluate(single)
        except (PolicyError, JournalError) as exc:
            return batch_failure(str(exc).strip("'\""), index)
        if outcome["status"] != "ok":
            return batch_failure(outcome["error"], index)
        results.append({"actions": outcome["actions"], "units": outcome["units"],
                        "operationId": operation_id})
    # Only deduplicated operations reach this sum, so a retry cannot push the
    # batch over its ceiling and two distinct IDs with equal parameters count
    # twice. Equality passes: the ceiling is a maximum, not a floor.
    total = sum(result["units"] for result in results)
    if total > limit:
        return batch_failure("batch-limit-exceeded", None)
    return {"status": "ok", "results": results, "units": total}

