"""JSON transport for the release planner.

The entrypoint owns transport only: read one JSON request from stdin, decide
whether it is a single-item request or a G4 `rollback-many` batch, and print
exactly one JSON object. Domain validation and computation stay in the other
modules; batch structure is the only decision made here.
"""
import json
import sys

from planner import plan, rollback_many

# G4: the only top-level fields a batch may carry. `limit` is now required and
# is validated by the planner (it owns the post-dedup comparison); anything
# else -- or a missing key -- is a malformed batch, which the transport layer
# reports before any element is looked at.
BATCH_FIELDS = {"action", "limit", "requests"}


def batch_failure(code, request_index):
    """Whole-batch error: no results, zero units, never a partial answer."""
    return {"status": "error", "error": code, "requestIndex": request_index,
            "results": [], "units": 0}


def batch_result(result):
    """Check the planner's batch answer and return the response to print."""
    if result.get("status") == "ok":
        # A success carries results in request order plus the summed units; the
        # single-item shape (status/actions/units) is not a valid batch envelope,
        # so it is downgraded here instead of being emitted under a wrong shape.
        # G4: each result also carries its `operationId`; a result missing it
        # means the planner broke its contract, so it is not emitted either.
        results = result.get("results")
        units = result.get("units")
        if (isinstance(results, list) and type(units) is int
                and all(isinstance(item, dict) and "operationId" in item
                        for item in results)):
            return {"status": "ok", "results": results, "units": units}
        return batch_failure("invalid-batch", None)
    # The request index is owned by the planner, which is the only layer that
    # knows which element failed; it is passed through unchanged (null only for a
    # whole-batch structure error).
    return batch_failure(result.get("error"), result.get("requestIndex"))


def run(request):
    """Dispatch one decoded request and return the response object."""
    if not isinstance(request, dict) or request.get("action") != "rollback-many":
        return plan(request)
    # Only an exact `{"action":"rollback-many","limit":n,"requests":[...]}`
    # envelope is a batch. Extra or missing top-level keys (G4 made `limit`
    # mandatory) and a `requests` value that is not a list fail the whole batch
    # as `invalid-batch` with a null index, because no element was picked out.
    # Element-level problems are the planner's business: it reports
    # `invalid-batch-item`, `conflicting-operation` or a per-item business
    # failure with the real index, so no partial results can ever be emitted.
    if set(request) != BATCH_FIELDS:
        return batch_failure("invalid-batch", None)
    return batch_result(rollback_many(request))


def main():
    try:
        request = json.load(sys.stdin)
    except (ValueError, TypeError):
        result = {"status": "error", "error": "invalid-json", "actions": [], "units": 0}
    else:
        result = run(request)
    print(json.dumps(result, separators=(",", ":")))


if __name__ == "__main__":
    main()

journal.py.text:
"""Normalize release records at the input boundary."""


class JournalError(ValueError):
    pass


def _id_list(entries, error):
    """Validate a JSON array of nonempty change IDs.

    `depends_on`, `applied` and `retain` share this shape. A bare string, an
    object, a number or a null is a malformed field, not an empty one; and the
    empty string does not name a change, so it is malformed too.
    """
    if not isinstance(entries, list):
        raise JournalError(error)
    for entry in entries:
        if not isinstance(entry, str) or not entry:
            raise JournalError(error)
    return entries


def _read_dependencies(row):
    return _id_list(row.get("depends_on", []), "invalid-change")


def read_changes(records):
    """Validate records, collapse identical duplicates and reject conflicting IDs."""
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    unique = {}
    for row in records:
        if (not isinstance(row, dict) or not isinstance(row.get("id"), str) or not row["id"]
                or not isinstance(row.get("component"), str) or not row["component"]
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        change = {
            "id": row["id"],
            "component": row["component"],
            "units": row["units"],
            "depends_on": frozenset(_read_dependencies(row)),
        }
        previous = unique.get(change["id"])
        if previous is None:
            unique[change["id"]] = change
        elif previous != change:
            raise JournalError("conflicting-change")
    return [unique[key] for key in sorted(unique)]


def read_applied(journal):
    """Validate the persisted release journal and return its unique change IDs."""
    return set(_id_list(journal, "invalid-change"))


def read_retain(request, applied):
    """Read the G2 rollback `retain` list: applied IDs that must remain installed.

    `retain` defaults to empty. Malformed lists are rejected here; an ID that is
    a valid string but was never applied is rejected here too, because that needs
    the persisted journal and no other module is allowed to own it. Repeated IDs
    are harmless; the value is consumed as a set.
    """
    retained = set(_id_list(request.get("retain", []), "invalid-retain"))
    if not retained <= applied:
        raise JournalError("invalid-retain")
    return retained

