import json

from journal import JournalError, read_applied, read_changes, read_retain
from policy import PolicyError, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


# G3: a batch is 1 to 128 independent rollback items.
BATCH_MIN_ITEMS = 1
BATCH_MAX_ITEMS = 128

# The only fields a batch item may carry; `action` is supplied by the batch
# entry, so an item that names its own action is a malformed element.
# G4 adds `operation_id` as a required field of every item.
BATCH_ITEM_FIELDS = {"environment", "budget", "changes", "applied", "retain",
                     "operation_id"}

